    { id: "de-b1-11.21", t: "speak", say: "Während wir warteten, tranken wir Tee.",
      e: "**Während**: w = “v”, ä uzun “e”: “vɛ:rent”. **warteten**: w = “v”, r hafif. **tranken**: tr- Türkçedeki gibi, a kısa. **Tee**: ee uzun “e”." },
    { id: "de-b1-11.22", t: "speak", say: "Bevor ich losgehe, rufe ich dich an.",
      e: "**Bevor**: be-**FOR**; v burada “f” gibi okunur. **ich** ve **dich**: ch “ç” ile “h” arası, damaktan; “iş” deme. **losgehe**: g Türkçedeki g, e sonda kısa “ə”." },
    { id: "de-b1-11.23", t: "respond", say: "Was machst du, bevor du schlafen gehst?",
      q: "Soruyu dinle ve 2–3 cümleyle cevap ver. *bevor*, *nachdem* ya da *während* kullan.",
      chunks: ["Bevor ich schlafe, …", "Nachdem ich … habe, …", "Während ich …, …"],
      models: ["Bevor ich schlafe, putze ich die Zähne. Nachdem ich gegessen habe, sehe ich noch ein bisschen fern. Während ich fernsehe, trinke ich Tee."],
      modelsN: ["Uyumadan önce dişlerimi fırçalarım. Yemek yedikten sonra biraz televizyon izlerim. Televizyon izlerken çay içerim."],
      e: "Yan cümlede **fiil sonda**: *Bevor ich **schlafe***. Yan cümle başa geçerse ana cümle fiille başlar: *Bevor ich schlafe, **putze** ich …* Türkçedeki *-meden önce* içindeki olumsuzluğu **taşıma**: ✗ *bevor ich nicht schlafe*. Cevabın örnekten farklı olabilir." },
    { id: "de-b1-11.24", t: "mc", q: "“Wenn ich in Bonn war, besuchte ich immer meine Tante.” – Cümle geçmişte olduğu hâlde neden **wenn**?", o: ["Çünkü olay geçmişte **tekrar eden** bir olay (her seferinde).", "Çünkü *wenn* her zaman geçmiş içindir.", "Çünkü Bonn bir şehir adıdır.", "Çünkü yan cümlede fiil sonda olmalıdır."], a: 0,
      why: { 1: "Tersi: *wenn* şimdiki zaman, gelecek ve **tekrar eden** olaylar içindir.", 2: "Şehir adının bağlaç seçimine etkisi yoktur.", 3: "Fiilin sonda olması hem *als* hem *wenn* için geçerlidir; seçimi belirleyen bu değil." },
      e: "Geçmişte bile, olay **tekrar** ediyorsa (*immer, jedes Mal, oft*) → **wenn**. Tek seferlik geçmiş olay → **als**." }
